// Silero VAD v6 16 kHz weights (MIT, Copyright (c) 2020-present Silero Team; see THIRD_PARTY_NOTICES.md).
// weights.bin holds the 14 tensors below as little-endian IEEE fp16, except the four conv biases
// (conv1B–conv4B), which are fp32: fp16 rounding of those biases alone moved p by up to 4.5e-3 (#44).
// The tensors are back to back, with no header.
// It is generated by scripts/extract-silero-weights.ts from the pinned upstream ONNX file; see
// weights.provenance.json. The STFT basis is not shipped: it is a periodic-Hann-windowed DFT and is
// regenerated in code.
// DOM-free (plan §3.3): runs unchanged in Node, the worklet and the worker.

export interface SileroWeights {
  conv1W: Float32Array;
  conv1B: Float32Array;
  conv2W: Float32Array;
  conv2B: Float32Array;
  conv3W: Float32Array;
  conv3B: Float32Array;
  conv4W: Float32Array;
  conv4B: Float32Array;
  lstmWih: Float32Array;
  lstmWhh: Float32Array;
  lstmBih: Float32Array;
  lstmBhh: Float32Array;
  finalW: Float32Array;
  finalB: Float32Array;
}

/** How one tensor is stored in weights.bin: little-endian IEEE binary16 or binary32. */
export type WeightsFormat = 'fp16' | 'fp32';

/** Bytes per value of each storage format. */
export const WEIGHTS_FORMAT_BYTES: Readonly<Record<WeightsFormat, number>> = { fp16: 2, fp32: 4 };

export interface WeightsLayoutEntry {
  readonly key: keyof SileroWeights;
  readonly onnxName: string;
  readonly dims: readonly number[];
  readonly format: WeightsFormat;
}

/**
 * The fixed tensor order and storage format of weights.bin. scripts/extract-silero-weights.ts asserts every
 * name and dims.
 */
export const WEIGHTS_LAYOUT: readonly WeightsLayoutEntry[] = [
  { key: 'conv1W', onnxName: 'model.encoder.0.reparam_conv.weight', dims: [128, 129, 3], format: 'fp16' },
  { key: 'conv1B', onnxName: 'model.encoder.0.reparam_conv.bias', dims: [128], format: 'fp32' },
  { key: 'conv2W', onnxName: 'model.encoder.1.reparam_conv.weight', dims: [64, 128, 3], format: 'fp16' },
  { key: 'conv2B', onnxName: 'model.encoder.1.reparam_conv.bias', dims: [64], format: 'fp32' },
  { key: 'conv3W', onnxName: 'model.encoder.2.reparam_conv.weight', dims: [64, 64, 3], format: 'fp16' },
  { key: 'conv3B', onnxName: 'model.encoder.2.reparam_conv.bias', dims: [64], format: 'fp32' },
  { key: 'conv4W', onnxName: 'model.encoder.3.reparam_conv.weight', dims: [128, 64, 3], format: 'fp16' },
  { key: 'conv4B', onnxName: 'model.encoder.3.reparam_conv.bias', dims: [128], format: 'fp32' },
  { key: 'lstmWih', onnxName: 'model.decoder.rnn.weight_ih', dims: [512, 128], format: 'fp16' },
  { key: 'lstmWhh', onnxName: 'model.decoder.rnn.weight_hh', dims: [512, 128], format: 'fp16' },
  { key: 'lstmBih', onnxName: 'model.decoder.rnn.bias_ih', dims: [512], format: 'fp16' },
  { key: 'lstmBhh', onnxName: 'model.decoder.rnn.bias_hh', dims: [512], format: 'fp16' },
  { key: 'finalW', onnxName: 'model.decoder.decoder.2.weight', dims: [1, 128, 1], format: 'fp16' },
  { key: 'finalB', onnxName: 'model.decoder.decoder.2.bias', dims: [1], format: 'fp16' },
];

/** 243,201 fp16 values × 2 bytes + 384 fp32 values (the conv biases) × 4 bytes. */
export const WEIGHTS_BYTES = 487_938;

/** SHA-256 of weights.bin, copied from weights.provenance.json (weights.test.ts asserts they match). */
export const WEIGHTS_SHA256 = 'a795abe08a96bb3c900d89085a3c5e6e4033675ec5f27c56790cbbec4152eb17';

/** Decodes one IEEE 754 binary16 bit pattern (0 … 0xffff) exactly. */
export function fp16ToFp32(bits: number): number {
  const sign = (bits & 0x8000) === 0 ? 1 : -1;
  const exp = (bits >>> 10) & 0x1f;
  const mant = bits & 0x3ff;
  if (exp === 0) return sign * mant * 2 ** -24;
  if (exp === 0x1f) return mant === 0 ? sign * Infinity : NaN;
  return sign * (0x400 + mant) * 2 ** (exp - 25);
}

/**
 * Decodes weights.bin (little-endian fp16 or fp32, per WEIGHTS_LAYOUT) into fp32 tensors, in WEIGHTS_LAYOUT
 * order.
 */
export function decodeWeights(buf: ArrayBuffer): SileroWeights {
  if (buf.byteLength !== WEIGHTS_BYTES) {
    throw new RangeError(`Silero weights: expected ${WEIGHTS_BYTES} bytes, got ${buf.byteLength}`);
  }
  const view = new DataView(buf);
  const tensor = (key: keyof SileroWeights): Float32Array => {
    let offset = 0;
    for (const entry of WEIGHTS_LAYOUT) {
      const length = entry.dims.reduce((a, b) => a * b, 1);
      if (entry.key === key) {
        const data = new Float32Array(length);
        if (entry.format === 'fp32') {
          for (let i = 0; i < length; i++) data[i] = view.getFloat32(offset + i * 4, true);
        } else {
          for (let i = 0; i < length; i++) data[i] = fp16ToFp32(view.getUint16(offset + i * 2, true));
        }
        return data;
      }
      offset += length * WEIGHTS_FORMAT_BYTES[entry.format];
    }
    throw new Error(`Silero weights: ${key} is not in WEIGHTS_LAYOUT`);
  };
  return {
    conv1W: tensor('conv1W'),
    conv1B: tensor('conv1B'),
    conv2W: tensor('conv2W'),
    conv2B: tensor('conv2B'),
    conv3W: tensor('conv3W'),
    conv3B: tensor('conv3B'),
    conv4W: tensor('conv4W'),
    conv4B: tensor('conv4B'),
    lstmWih: tensor('lstmWih'),
    lstmWhh: tensor('lstmWhh'),
    lstmBih: tensor('lstmBih'),
    lstmBhh: tensor('lstmBhh'),
    finalW: tensor('finalW'),
    finalB: tensor('finalB'),
  };
}
